  6225	#define HELM_SB_IN_GAP  80u    /**< 组间错开 ms。 */
  6226	#define HELM_SB_IN_DLY  40u    /**< 第一组延迟 ms：让页面底色/页面级 fade 先落定。 */
  6227	#define HELM_SB_IN_DY   12     /**< 入场起始下移量 px。 */
  6228	
  6229	/** @brief 入场 exec：一个 0→255 的进度同时驱动不透明度与下移量。 */
  6230	static void helm_sb_in_exec(void * var, int32_t v)
  6231	{
  6232	    lv_obj_t * obj = (lv_obj_t *)var;
  6233	    int32_t dy;
  6234	
  6235	    if (helm_anim_is_suspended()) {
  6236	        return;
  6237	    }
  6238	
  6239	    if (v < 0) {
  6240	        v = 0;
  6241	    } else if (v > 255) {
  6242	        v = 255;
  6243	    }
  6244	
  6245	    lv_obj_set_style_opa(obj, (lv_opa_t)v, 0);
  6246	    /* v=0 ⇒ 全透明且下移 HELM_SB_IN_DY(12)px；v=255 ⇒ 归位。四舍五入到整像素。 */
  6247	    dy = ((255 - v) * HELM_SB_IN_DY + 127) / 255;
  6248	    lv_obj_set_style_translate_y(obj, (lv_coord_t)dy, 0);
  6249	}
  6250	
  6251	/** @brief 入场末态：显式复位（全不透明 + 原位），不依赖最后一帧是否被挂起。 */
  6252	static void helm_sb_in_settle(lv_obj_t * obj)
  6253	{
  6254	    if (obj == NULL) {
  6255	        return;
  6256	    }
  6257	
  6258	    lv_obj_set_style_opa(obj, LV_OPA_COVER, 0);
  6259	    lv_obj_set_style_translate_y(obj, 0, 0);
  6260	}
  6261	
  6262	static void helm_sb_in_done(lv_anim_t * a)
  6263	{
