  6269	/** @brief 兜底：等重建超时仍没来 ⇒ 把三组落末态，别让它们一直是透明的。 */
  6270	static void helm_sb_in_wait_cb(lv_timer_t * t)
  6271	{
  6272	    lv_obj_t * objs[3];
  6273	
  6274	    if (t != NULL && t == s_sb_in_wait) {
  6275	        s_sb_in_wait = NULL;
  6276	    }
  6277	
  6278	    objs[0] = s_sh.sb_clock;
  6279	    objs[1] = s_sh.sb_stat;
  6280	    objs[2] = s_sh.sb_cta;
  6281	
  6282	    for (uint32_t i = 0; i < 3u; i++) {
  6283	        if (s_theme_rebuild_pending) {
  6284	            break;                 /* 重建真的要来了：交给重建末尾那一轮 */
  6285	        }
  6286	        helm_anim_stop(objs[i], helm_sb_in_exec);
  6287	        helm_sb_in_settle(objs[i]);
  6288	    }
  6289	}
