  6291	/** @brief 起一组：先清同对象旧动画并同步落起始态，再走一条带 delay 的 lv_anim。 */
  6292	static void helm_sb_in_run(lv_obj_t * obj, uint32_t delay)
  6293	{
  6294	    lv_anim_t a;
  6295	
  6296	    if (obj == NULL) {
  6297	        return;
  6298	    }
  6299	
  6300	    /* 等同 helm_anim_run 的约定：同 var + exec 的旧动画先删。 */
  6301	    helm_anim_stop(obj, helm_sb_in_exec);
  6302	    /* 起始态同步落位：上一轮若被打断（快速退出/换主题重建），
  6303	     * 避免先闪一帧旧位置/旧透明度再从头走。 */
  6304	    helm_sb_in_exec(obj, 0);
  6305	
  6306	    lv_anim_init(&a);
  6307	    lv_anim_set_var(&a, obj);
  6308	    lv_anim_set_values(&a, 0, 255);
  6309	    lv_anim_set_duration(&a, HELM_SB_IN_MS);
  6310	    lv_anim_set_delay(&a, delay);
  6311	    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
  6312	    lv_anim_set_exec_cb(&a, helm_sb_in_exec);
  6313	    lv_anim_set_completed_cb(&a, helm_sb_in_done);
  6314	    if (lv_anim_start(&a) == NULL) {
  6315	        /* 动画对象分配失败（内存紧张）⇒ 没有 completed 回调，必须立刻落末态，
  6316	         * 否则这一组会永久停在 opa=0（周期刷新不会重跑入场）。 */
  6317	        helm_sb_in_settle(obj);
  6318	    }
  6319	}
