  6321	/**
  6322	 * @brief 主界面入场动效（幂等，可重复调用）。
  6323	 *
  6324	 * @details 触发点两处：① `map_will_appear()`（开机 splash 关闭后进主界面、
  6325	 *          从菜单/USB/工厂页回到主界面）；② `helm_shell_rebuild_once()` 末尾
  6326	 *          （换主题把控件换新后重播）。两处互斥，见文件里的 `s_theme_rebuild_pending` 说明。
  6327	 * @note 卡片此刻不可见（骑行页）或屏幕挂起：不播，但必须落到末态 ——
  6328	 *       下次显示时不能是一块透明的卡片。
  6329	 */
  6330	void helm_shell_enter_anim(void)
  6331	{
  6332	    static const uint32_t delays[3] = {
  6333	        HELM_SB_IN_DLY, HELM_SB_IN_DLY + HELM_SB_IN_GAP,
  6334	        HELM_SB_IN_DLY + 2u * HELM_SB_IN_GAP
  6335	    };
  6336	    lv_obj_t * objs[3];
  6337	    uint32_t i;
  6338	
  6339	    if (!s_sh.attached) {
  6340	        return;
  6341	    }
  6342	
  6343	    objs[0] = s_sh.sb_clock;
  6344	    objs[1] = s_sh.sb_stat;
  6345	    objs[2] = s_sh.sb_cta;
  6346	
  6347	    /*
  6348	     * 有待办主题重建：重建会把这三个对象整批换新（`helm_shell_rebuild_once` 末尾
  6349	     * 还会再调一次本函数，那一轮才真正播）。这一轮**不能**落末态：页面 220 ms
  6350	     * 淡入会把旧控件先亮出来，随后重建换新、新控件再从 0 淡入 ⇒ 内容"出现→消失→
  6351	     * 再出现"。所以这里保持它们不可见，让页面淡入时这块本来就没内容。
  6352	     *
  6353	     * 兜底：万一重建没来（不在主界面/转场一直没结束），一次性定时器在 500 ms 后
  6354	     * 落末态，绝不把时钟/状态列/操作条永久留在透明。
  6355	     */
  6356	    if (s_theme_rebuild_pending) {
  6357	        for (i = 0; i < 3u; i++) {
  6358	            helm_anim_stop(objs[i], helm_sb_in_exec);
  6359	            helm_sb_in_exec(objs[i], 0);
  6360	        }
  6361	
  6362	        if (s_sb_in_wait == NULL) {
  6363	            s_sb_in_wait = lv_timer_create(helm_sb_in_wait_cb, 500, NULL);
  6364	            if (s_sb_in_wait != NULL) {
  6365	                lv_timer_set_repeat_count(s_sb_in_wait, 1);
  6366	            }
  6367	        }
  6368	        return;
  6369	    }
  6370	
  6371	    /* 有兜底在等 ⇒ 这一轮是重建后的真正入场，撤掉它（否则它会在 500 ms 处
  6372	     * 把动画中途落末态）。 */
  6373	    if (s_sb_in_wait != NULL) {
  6374	        lv_timer_delete(s_sb_in_wait);
  6375	        s_sb_in_wait = NULL;
  6376	    }
  6377	
  6378	    if (!helm_obj_shown(s_sh.sb_card) || helm_anim_is_suspended()) {
  6379	        for (i = 0; i < 3u; i++) {
  6380	            helm_anim_stop(objs[i], helm_sb_in_exec);
  6381	            helm_sb_in_settle(objs[i]);
  6382	        }
  6383	        return;
  6384	    }
  6385	
  6386	    for (i = 0; i < 3u; i++) {
  6387	        helm_sb_in_run(objs[i], delays[i]);
  6388	    }
  6389	}
