  7787	/** @brief attach 之前 root 已有的子对象数（地铁画布等外来件个数，重建时保留）。 */
  7788	static uint8_t s_build_keep_n;
  7789	
  7790	/** @brief 换主题后用：本层重建一遍（颜色是建页时烘进样式的）。
  7791	 *
  7792	 *  @details `helm_color()` 的值写在 `lv_obj_set_style_*` 那一刻 ⇒ 换主题只
  7793	 *           `lv_obj_invalidate()` 只是"把旧样子重画一遍"，必须**重建对象**才能重新
  7794	 *           取值。菜单那边靠 `helm_menu_paint()` 重建行，本层靠这里。
  7795	 *
  7796	 *  @note 只删**本层自己建**的对象（`helm_shell_attach()` 里打过 LV_OBJ_FLAG_USER_2
  7797	 *        标记的）；地图画布等外来件（vmap 建的兄弟节点）必须留着 —— 待机 pane 的
  7798	 *        注释里记着"地图画布从没被绘制过"那次花屏的教训。 */
  7799	/** @brief 重入保护：本函数正在重建时，内层再进来直接返回。
  7800	 *
  7801	 *  @details 2026-09-26 上板实测：把 `helm_shell_rebuild()` 接进换主题通知后，
  7802	 *           **一次切换就把 UI 卡死**（log 停住、无 panic/assert = 硬挂）。
  7803	 *           机制是重入：重建走 `helm_shell_attach()` → 各 builder →
  7804	 *           其中有 `map_page_set_map_ui_visible()` 一类会**再触发一次主题通知**，
  7805	 *           于是内层又一次进来删对象 —— **删的正是外层正在遍历的子对象**，
  7806	 *           链表当场错乱。所以保护的不是"重复做功"，是**外层的遍历**。
  7807	 *  @note 内层返回后外层照常跑完，本轮重建仍然生效（不是"跳过"）。 */
  7808	static bool s_rebuilding;
  7809	
  7810	static void helm_shell_rebuild_once(void)
  7811	{
  7812	    map_page_t * map = s_sh.map;
  7813	    lv_obj_t * root;
  7814	    uint32_t i;
  7815	
  7816	    if (map == NULL || !s_sh.attached) {
  7817	        return;
  7818	    }
  7819	
  7820	    root = map_page_root(map);
  7821	    if (root == NULL) {
  7822	        return;
  7823	    }
  7824	
  7825	    /* 换主题才走这里 ⇒ 打点不心疼：真卡住时"最后一行"就是现场（这一族踩过两次）。 */
  7826	    syslog(LOG_WARNING, "[theme] delete begin n=%u",
  7827	           (unsigned)lv_obj_get_child_count(root));
  7828	
  7829	    for (i = lv_obj_get_child_count(root); i > 0u; i--) {
  7830	        lv_obj_t * c = lv_obj_get_child(root, i - 1u);
  7831	
  7832	        if (c != NULL && lv_obj_has_flag(c, LV_OBJ_FLAG_USER_2)) {
  7833	            lv_obj_delete(c);
  7834	        }
  7835	    }
  7836	
  7837	    syslog(LOG_WARNING, "[theme] delete done");
  7838	
  7839	    s_sh.attached = false;
  7840	    helm_shell_attach(map);        /* 按开机顺序重建 */
  7841	    syslog(LOG_WARNING, "[theme] attach done");
  7842	    helm_apply_view();             /* 恢复当前页 */
  7843	    syslog(LOG_WARNING, "[theme] view done");
  7844	
  7845	    /*
  7846	     * 重建把上一轮入场动画的对象一起删了（`lv_obj_delete` 会清掉挂在对象上的
  7847	     * 动画），新控件默认全不透明 ⇒ 若此时首轮错峰还在跑，看起来就是"第三组被砍断、
  7848	     * 新控件直接全显"。重建发生在主界面且转场已结束（见 `helm_shell_theme_apply`），
  7849	     * 正好是重播一次入场的时机；两处触发都幂等，不会叠出两轮。
  7850	     */
  7851	    helm_shell_enter_anim();
  7852	}
