  7854	void helm_shell_rebuild(void)
  7855	{
  7856	    if (s_rebuilding) {
  7857	        return;                    /* 内层重入：见 s_rebuilding 的注释，这里是防挂的关键 */
  7858	    }
  7859	
  7860	    s_rebuilding = true;
  7861	    helm_shell_rebuild_once();
  7862	    s_rebuilding = false;
  7863	
  7864	    /*
  7865	     * ⚠ 换主题后的"剖面重烘焙"必须登记在**重建之后**（对象是新的）：绘制路径拿到这个标志
  7866	     * 会用既有数据 `helm_climb_canvas_bake()` 重烘；若重建把剖面数据也清了（日志里的
  7867	     * `[theme] hist_reset`），bake() 返回假 ⇒ 走正常 reload 重新取数再烘 —— 两条路都不会
  7868	     * 留下空白，也不会烘在已被删除的对象上（2026-09-27 打桩定位到的顺序问题）。
  7869	     */
  7870	    s_climb_rebake = true;
  7871	
  7872	    /*
  7873	     * ⚠ 还要作废**剖面指纹**：`s_climb_eles[]`（每点海拔）与 `s_climb_zone[]`（坡度分段）
  7874	     * 是静态缓存，它们的重算被"点数 / 总里程"指纹挡着 —— 而**重建不等于指纹变化**
  7875	     * （点数、总里程都没变）⇒ 重建把数组清掉后重算会被跳过 ⇒ 烘焙出来的折线是空的。
  7876	     */
  7877	    s_climb_fp_pts = 0xffffffffu;
  7878	    s_climb_fp_total_cm = 0xffffffffu;
  7879	    s_climb_fp_rec_n = 0xff;
  7880	    s_climb_fp_rec_slot = 0xffffffffu;
  7881	}
